const items = $input.all();

return items.map(item => {
  const result = item.json.chart?.result?.[0];

  if (!result) {
    return {
      json: {
        symbol: "UNKNOWN",
        error: "Data saham tidak ditemukan"
      }
    };
  }

  const symbol = result.meta.symbol;
  const price = result.meta.regularMarketPrice;
  const rawClose = result.indicators.quote[0].close;
  const close = rawClose.filter(v => v !== null && Number.isFinite(v));

  function sma(values, period) {
    if (values.length < period) return null;
    const lastValues = values.slice(-period);
    return lastValues.reduce((sum, v) => sum + v, 0) / period;
  }

  function rsi(values, period = 14) {
    if (values.length <= period) return null;

    const changes = [];
    for (let i = 1; i < values.length; i++) {
      changes.push(values[i] - values[i - 1]);
    }

    const recent = changes.slice(-period);
    const gains = recent.filter(v => v > 0);
    const losses = recent.filter(v => v < 0).map(v => Math.abs(v));

    const avgGain = gains.reduce((a, b) => a + b, 0) / period;
    const avgLoss = losses.reduce((a, b) => a + b, 0) / period;

    if (avgLoss === 0) return avgGain === 0 ? 50 : 100;

    const rs = avgGain / avgLoss;
    return 100 - (100 / (1 + rs));
  }

  const sma50 = sma(close, 50);
  const sma200 = sma(close, 200);
  const rsi14 = rsi(close);

  const signals = [];

  if (sma50 !== null && sma200 !== null && sma50 > sma200) {
    signals.push("Golden Cross (MA50 > MA200)");
  }

  if (rsi14 !== null && rsi14 < 30) {
    signals.push("RSI Oversold");
  }

  return {
    json: {
      symbol,
      price,
      sma50,
      sma200,
      rsi14,
      signals,
      alert: signals.length > 0
    }
  };
});

const result = $input.first().json.chart?.result?.[0];

if (!result) {
  throw new Error("Data BTC/USD tidak ditemukan");
}

const quote = result.indicators.quote[0];
const closes = quote.close.filter(
  v => v !== null && Number.isFinite(v)
);

function sma(values, period) {
  if (values.length < period) return null;

  const recent = values.slice(-period);
  return recent.reduce((sum, v) => sum + v, 0) / period;
}

function rsi(values, period = 14) {
  if (values.length <= period) return null;

  const changes = [];

  for (let i = 1; i < values.length; i++) {
    changes.push(values[i] - values[i - 1]);
  }

  const recent = changes.slice(-period);
  const gains = recent.filter(v => v > 0);
  const losses = recent
    .filter(v => v < 0)
    .map(v => Math.abs(v));

  const avgGain =
    gains.reduce((a, b) => a + b, 0) / period;
  const avgLoss =
    losses.reduce((a, b) => a + b, 0) / period;

  if (avgLoss === 0) {
    return avgGain === 0 ? 50 : 100;
  }

  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

const price = result.meta.regularMarketPrice;
const sma50 = sma(closes, 50);
const sma200 = sma(closes, 200);
const rsi14 = rsi(closes);

const signals = [];

if (sma50 !== null && sma200 !== null) {
  if (sma50 > sma200) {
    signals.push("Golden Cross (MA50 > MA200)");
  } else if (sma50 < sma200) {
    signals.push("Death Cross (MA50 < MA200)");
  }
}

if (rsi14 !== null && rsi14 < 30) {
  signals.push("RSI Oversold");
}

if (rsi14 !== null && rsi14 > 70) {
  signals.push("RSI Overbought");
}

return [{
  json: {
    symbol: result.meta.symbol,
    price,
    sma50,
    sma200,
    rsi14,
    signals,
    alert: signals.length > 0
  }
}];
